function setup() {
  createCanvas(640, 640);
  noStroke();
  fill(234, 46, 73);
}

function draw() {
  background(51, 55, 69);
  translate(width/2, height/2);
  // let amount of layers
  for (let j = 20; j < 120; j+=20) {
    let h = j*2+5;
    // let amount of shapes per layer
    for (let q = 0; q < 360; q+=30) {
      let x2 = sin(radians(q+h))*j;
      let y2 = cos(radians(q+h))*j;
      let d = map(dist(x2, y2, 0, 0), 0, 120, 0, 360);
      push();
      translate(x2, y2);
      scale(map(j, 0, 180, 0.1, 0.4));
      rotate(radians(-q-h));
      beginShape();
      // let shape, made from openprocessing.org/sketch/162912
      for (let i = 0; i < 180; i+=5) {
        let x = sin(radians(i)) * i/3;
        let angle = sin(radians(i+frameCount*3+d)) * 50;
        vertex(x-angle, i*2);
      }
      for (let i = 180; i > 0; i-=5) {
        var x = sin(radians(i)) * i/3;
        var angle = sin(radians(i+frameCount*3+d)) * 50;
        vertex(-x-angle, i*2);
      }
      endShape(CLOSE);
      pop();
    }
  }
}
